//go:build amd64

package per

import (
	"github.com/thebagchi/asn1c-go/lib/cpu"
)

// How much each septet kernel handles per iteration, in characters and in octets.
// SEPTET_KERNELS says that this architecture has the kernels, so the decoder reads its
// chunks for them.
const (
	SEPTET_SSE2_CHARS  = 16
	SEPTET_SSE2_OCTETS = 14
	SEPTET_AVX2_CHARS  = 32
	SEPTET_AVX2_OCTETS = 28
	// The AVX-512 block is twice the AVX2 block.
	SEPTET_AVX512_CHARS  = 64
	SEPTET_AVX512_OCTETS = 56
	SEPTET_KERNELS       = true
)

// The kernels are generated by avo from gen/septet.go into septet_amd64.s. go vet's asmdecl
// check holds the declarations below and the assembly's frames in step. Regenerate with
// "make generate" after editing anything under gen/.
//
//go:generate go run ./gen -only septet -out septet_amd64.s -pkg per

// _PackSeptetKernels packs whole blocks of text into dst with the assembly kernels, AVX-512,
// then AVX2, then SSE2 on what each leaves, and returns how many characters they took: a
// multiple of sixteen. A block runs only when its stores, which reach one or two octets past
// its output, stay inside dst; the caller packs the rest.
//
// The kernels are called by name, for the reason _PackNumeric gives, and the AVX2 and
// AVX-512 kernels end in VZEROUPPER.
//
// Revisions:
//   - 2026-10-21 22:05: initial creation (review P32)
//   - 2026-10-21 23:57: the AVX-512 kernel runs first when cpu.HAS_AVX512 (review P33)
func _PackSeptetKernels(
	dst,
	text []byte,
) int {
	done := _PackSeptetBlocksAVX512(
		dst,
		text,
	)

	if cpu.HAS_AVX2 {
		var (
			out    = done / SEPTET_AVX2_CHARS * SEPTET_AVX2_OCTETS
			blocks = min(
				(len(text)-done)/SEPTET_AVX2_CHARS,
				(len(dst)-out-SEPTET_PACK_SLACK)/SEPTET_AVX2_OCTETS,
			)
		)
		if blocks > 0 {
			done += _PackSeptetsAVX2(
				dst[out:],
				text[done:done+blocks*SEPTET_AVX2_CHARS],
			)
		}
	}

	var (
		out    = done / SEPTET_SSE2_CHARS * SEPTET_SSE2_OCTETS
		blocks = min(
			(len(text)-done)/SEPTET_SSE2_CHARS,
			(len(dst)-out-1)/SEPTET_SSE2_OCTETS,
		)
	)

	if blocks > 0 {
		done += _PackSeptetsSSE2(
			dst[out:],
			text[done:done+blocks*SEPTET_SSE2_CHARS],
		)
	}

	return done
}

// _SpreadSeptetKernels spreads whole blocks of the packed src into the characters of dst
// with the assembly kernels, AVX-512, then AVX2, then SSE2 on what each leaves, and returns
// how many characters they wrote: a multiple of sixteen. A block runs only when its loads,
// which reach one or two octets past its input, stay inside src.
//
// Revisions:
//   - 2026-10-21 22:05: initial creation (review P32)
//   - 2026-10-21 23:57: the AVX-512 kernel runs first when cpu.HAS_AVX512 (review P33)
func _SpreadSeptetKernels(
	dst,
	src []byte,
) int {
	done := _SpreadSeptetBlocksAVX512(
		dst,
		src,
	)

	if cpu.HAS_AVX2 {
		var (
			in     = done / SEPTET_AVX2_CHARS * SEPTET_AVX2_OCTETS
			blocks = min(
				(len(dst)-done)/SEPTET_AVX2_CHARS,
				(len(src)-in-SEPTET_PACK_SLACK)/SEPTET_AVX2_OCTETS,
			)
		)
		if blocks > 0 {
			done += _SpreadSeptetsAVX2(
				dst[done:done+blocks*SEPTET_AVX2_CHARS],
				src[in:],
			)
		}
	}

	var (
		in     = done / SEPTET_SSE2_CHARS * SEPTET_SSE2_OCTETS
		blocks = min(
			(len(dst)-done)/SEPTET_SSE2_CHARS,
			(len(src)-in-1)/SEPTET_SSE2_OCTETS,
		)
	)

	if blocks > 0 {
		done += _SpreadSeptetsSSE2(
			dst[done:done+blocks*SEPTET_SSE2_CHARS],
			src[in:],
		)
	}

	return done
}

// _PackSeptetBlocksAVX512 packs the whole AVX-512 blocks of text into dst when
// cpu.HAS_AVX512, and returns how many characters it took. A block runs only when its
// stores stay inside dst.
//
// Revisions:
//   - 2026-10-22 00:01: initial creation, split out of _PackSeptetKernels (review P33)
func _PackSeptetBlocksAVX512(
	dst,
	text []byte,
) int {
	if !cpu.HAS_AVX512 {
		return 0
	}

	blocks := min(
		len(text)/SEPTET_AVX512_CHARS,
		(len(dst)-SEPTET_PACK_SLACK)/SEPTET_AVX512_OCTETS,
	)
	if blocks <= 0 {
		return 0
	}

	return _PackSeptetsAVX512(
		dst,
		text[:blocks*SEPTET_AVX512_CHARS],
	)
}

// _SpreadSeptetBlocksAVX512 spreads the whole AVX-512 blocks of src into dst when
// cpu.HAS_AVX512, and returns how many characters it wrote. A block runs only when its
// loads stay inside src.
//
// Revisions:
//   - 2026-10-22 00:01: initial creation, split out of _SpreadSeptetKernels (review P33)
func _SpreadSeptetBlocksAVX512(
	dst,
	src []byte,
) int {
	if !cpu.HAS_AVX512 {
		return 0
	}

	blocks := min(
		len(dst)/SEPTET_AVX512_CHARS,
		(len(src)-SEPTET_PACK_SLACK)/SEPTET_AVX512_OCTETS,
	)
	if blocks <= 0 {
		return 0
	}

	return _SpreadSeptetsAVX512(
		dst[:blocks*SEPTET_AVX512_CHARS],
		src,
	)
}

// _PackSeptetsSSE2 packs the 7-bit characters of src into dst, leading bit first, sixteen
// characters per iteration, and returns how many characters it consumed: a multiple of
// sixteen. len(dst) must be at least 14*(len(src)/16)+1. It is declared noescape so a
// caller's stack buffer stays where it is, as are the three below.
//
// Revisions:
//   - 2026-10-21 22:05: initial creation (review P32)
//
//go:noescape
func _PackSeptetsSSE2(
	dst,
	src []byte,
) int

// _PackSeptetsAVX2 is _PackSeptetsSSE2 at thirty-two characters per iteration. len(dst)
// must be at least 28*(len(src)/32)+2.
//
// Revisions:
//   - 2026-10-21 22:05: initial creation (review P32)
//
//go:noescape
func _PackSeptetsAVX2(
	dst,
	src []byte,
) int

// _SpreadSeptetsSSE2 spreads 7-bit characters from src into the octets of dst, sixteen per
// iteration, and returns how many it wrote: a multiple of sixteen, no more than len(dst).
// len(src) must be at least 14*(len(dst)/16)+1.
//
// Revisions:
//   - 2026-10-21 22:05: initial creation (review P32)
//
//go:noescape
func _SpreadSeptetsSSE2(
	dst,
	src []byte,
) int

// _SpreadSeptetsAVX2 is _SpreadSeptetsSSE2 at thirty-two characters per iteration.
// len(src) must be at least 28*(len(dst)/32)+2.
//
// Revisions:
//   - 2026-10-21 22:05: initial creation (review P32)
//
//go:noescape
func _SpreadSeptetsAVX2(
	dst,
	src []byte,
) int

// _PackSeptetsAVX512 is _PackSeptetsSSE2 at sixty-four characters per iteration, in EVEX
// forms only. len(dst) must be at least 56*(len(src)/64)+2. Call it only when
// cpu.HAS_AVX512.
//
// Revisions:
//   - 2026-10-21 23:57: initial creation (review P33)
//
//go:noescape
func _PackSeptetsAVX512(
	dst,
	src []byte,
) int

// _SpreadSeptetsAVX512 is _SpreadSeptetsSSE2 at sixty-four characters per iteration, in EVEX
// forms only. len(src) must be at least 56*(len(dst)/64)+2. Call it only when
// cpu.HAS_AVX512.
//
// Revisions:
//   - 2026-10-21 23:57: initial creation (review P33)
//
//go:noescape
func _SpreadSeptetsAVX512(
	dst,
	src []byte,
) int
